using UnityEngine;

[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class MoonlitMeshSource : MonoBehaviour
{
    public MoonlitProceduralMeshes.Kind meshKind = MoonlitProceduralMeshes.Kind.LotusLantern;
    // On the saved scene the MeshFilter references an asset generated by this same algorithm.
    // The fallback allows an empty object with this component to generate its own mesh in Play mode.
    void Awake()
    {
        var filter = GetComponent<MeshFilter>();
        if (filter.sharedMesh == null) filter.sharedMesh = MoonlitProceduralMeshes.Build(meshKind);
    }
}
